"""Collect V25 frozen regressions, original failures and decoded public evidence."""
from datetime import datetime,timezone
from pathlib import Path
import hashlib,json,re,shutil,subprocess
root=Path(__file__).resolve().parents[2];runtime=root/'product/.runtime';out=root/'docs/validation/evidence'
def load(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def sha(p):return 'sha256:'+hashlib.sha256(p.read_bytes()).hexdigest()
verification={k:load(runtime/f'nested-coverage-accepted-{k}-20261017.json') for k in ('full','adjacent','before')}
full,adjacent,before=[verification[k] for k in ('full','adjacent','before')]
assert full['status']=='passed' and full['test_count']==537 and full['frozen_file_count']==100
assert adjacent['status']=='passed' and adjacent['test_count']==79
assert before['test_count']==13 and before['exit_code']==1 and before['failure_records']==8
for r in verification.values():assert r['frozen_before']==r['frozen_after']==full['frozen_after']
for name,digest in full['frozen_after'].items():assert sha(root/name)==digest,name
public=load(root/'docs/assets/nested-frame-coverage-20261017/evidence.json');audit=load(runtime/'nested-coverage-independent-20261017.json')
assert public['frozen_before']==public['frozen_after']==full['frozen_after']
assert audit['public_evidence_sha256']==sha(root/'docs/assets/nested-frame-coverage-20261017/evidence.json')
assert public['generator_sha256']==sha(root/'scripts/smoke_nested_frame_coverage.py')
assert public['baseline_ref']==before['baseline_ref']=='10f035c0c27727a8b0300e8220d264fc1873faa6'
methods=set(re.findall(r'^    def (test_\w+)\(', (root/'product/tests/test_nested_frame_coverage.py').read_text(encoding='utf-8-sig'),re.M))
failures=set(re.findall(r'^(?:FAIL|ERROR): (test_\w+)',(runtime/'nested-coverage-accepted-before-20261017.log').read_text(encoding='utf-8-sig'),re.M))
assert len(methods)==13 and len(failures)==8 and failures<=methods
assert len(public['records'])==10 and [n for n,r in public['records'].items() if not r['full_delivery_verified']]==['tiny-forward','tiny-reverse']
counts={key:sum(c['args'][0]==key for c in public['calls']) for key in ('project','media','timeline','render','quality','policy')}
assert len(public['calls'])==85 and counts=={'project':10,'media':21,'timeline':12,'render':22,'quality':10,'policy':10}
failed_calls=[c for c in public['calls'] if c['exit_code']!=0];assert len(failed_calls)==2 and all(c['args'][0]=='quality' for c in failed_calls)
assert audit['new_main_frames']==496 and audit['control_frames']==116 and audit['passed_deliveries']==8 and audit['failed_deliveries']==2
assert all(r['variants']['after']['full_frame_coverage_passed'] for r in public['records'].values())
logs={}
for p in sorted(runtime.glob('nested-coverage-*-20261017.log')):
 name=p.name.replace('nested-coverage-accepted-','nested-coverage-')
 destination=out/name
 if destination.exists():assert destination.read_bytes()==p.read_bytes(),name
 else:shutil.copyfile(p,destination)
 logs[name]={'sha256':sha(destination),'bytes':destination.stat().st_size}
for mode,r in verification.items():assert logs[f'nested-coverage-{mode}-20261017.log']['sha256']==r['log_sha256']
media_execution=load(runtime/'nested-coverage-accepted-media-20261017.json')
assert media_execution['exit_code']==0 and media_execution['log_sha256']==logs['nested-coverage-media-20261017.log']['sha256']
stages={p.name:load(p) for p in runtime.glob('nested-coverage-development-*-20261017.json')}
stages['preflight-v1']={'status':'failed-at-short-audio-quality','calls':load(runtime/'nested-coverage-preflight-v1-work-20261017/partial-calls.json'),'not_in_accepted_counts':True}
stages['preflight-v2']={'status':'completed-with-one-audio-delivery-failure','evidence':load(runtime/'nested-coverage-preflight-v2-media-20261017/evidence.json'),'not_in_accepted_counts':True}
stages['initial-independent-gif-guard']={'status':'audit-assertion-corrected','expected':52,'actual_encoded_gif_frames':45,'requested_display_slots':52,'actual_duration_ms':2170,'raw_traceback_file_retained':False,'description':'Pillow merges identical neighboring GIF frames. Corrected auditor to verify 45 encoded frames and 2170 ms against 52 requested display slots; product, generator and public media unchanged.'}
sources={}
for name,digest in public['baseline_source_sha256'].items():
 raw=subprocess.run(['git','-c','core.autocrlf=false','show',public['baseline_ref']+':'+name],cwd=root,capture_output=True,check=True).stdout
 assert 'sha256:'+hashlib.sha256(raw).hexdigest()==digest;sources[name]=digest
diagnostic={}
for folder in ('nested-eof-diagnosis-20261017','short-atempo-probe-20261017'):
 diagnostic[folder]={'results':load(runtime/folder/'result.json'),'files':{}}
 for p in sorted((runtime/folder).iterdir()):
  if p.is_file():
   item={'sha256':sha(p),'bytes':p.stat().st_size}
   if p.suffix in ('.log','.ffgraph'):item['utf8']=p.read_text(encoding='utf-8-sig',errors='replace')
   diagnostic[folder]['files'][p.name]=item
helpers={}
for name in ('collect_nested_coverage_evidence_20261017.py','verify_nested_coverage_20261017.py','run_nested_coverage_media_20261017.py','audit_nested_coverage_20261017.py','diagnose_nested_eof_20261017.py','probe_short_atempo_20261017.py','update_nested_coverage_docs_20261017.py','audit_nested_coverage_docs_20261017.py','audit_nested_coverage_skills_20261017.py','stage_nested_coverage_20261017.py'):
 p=runtime/name;helpers[p.relative_to(root).as_posix()]={'sha256':sha(p),'utf8_source':p.read_text(encoding='utf-8-sig')}
files={p.relative_to(root).as_posix():{'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted((root/'docs/assets/nested-frame-coverage-20261017').iterdir()) if p.is_file()}
assert len(files)==85
record={'collected_at_utc':datetime.now(timezone.utc).isoformat(),'verification':verification,'new_test_methods':sorted(methods),'baseline_failing_methods':sorted(failures),'baseline_passing_control_methods':sorted(methods-failures),
 'development_and_preflight':stages,'logs':logs,'public_media_execution':media_execution,'native_diagnostics_not_integrated_audio':diagnostic,'baseline_ref':public['baseline_ref'],'baseline_git_blob_sha256':sources,
 'public_generator_sha256':sha(root/'scripts/smoke_nested_frame_coverage.py'),'clock_oracle_sha256':sha(root/'scripts/smoke_speed_easing.py'),'public_evidence_sha256':sha(root/'docs/assets/nested-frame-coverage-20261017/evidence.json'),
 'independent_decoded_delivery':audit,'public_files':files,'call_counts':counts,'actual_cli_calls':85,'successful_cli_calls':83,'failed_cli_calls':failed_calls,'formal_render_variants':22,'passed_deliveries':8,'failed_deliveries':2,
 'new_main_frames_including_failed_delivery':496,'passed_delivery_main_frames':466,'control_frames':116,'old_main_frames_separately_counted':496,'helper_files':helpers,'new_model_inference':0,
 'remaining_failures':{'cases':['tiny-forward','tiny-reverse'],'quality_code':'OUTPUT_TRUE_PEAK_UNAVAILABLE','decoded_pcm_nonzero_samples':0,'status':'audio-and-complete-delivery-not-accepted','description':'4 ms authored tone slowed to 250 ms produces zero atempo samples and existing apad fills silence. PCM equality alone cannot pass delivery. Native padding/rubberband probes are diagnostics only and are not product fixes.'},
 'historical_v24_failure_rechecked':{'case':'retained-typing-tail','old_visibility_failure_frames':[50,51],'new_visibility_failure_frames':[],'new_max_source_frame_error':0,'status':'passed-for-this-controlled-recheck','historical_evidence_unchanged':True}}
record['static_visual_review']={'date':'2026-10-17','method':'Native image tool inspection, separate from automated decoding',
 'images':{n:sha(root/n) for n in ('docs/assets/nested-frame-coverage-20261017/contact-sheet.png','docs/assets/nested-frame-coverage-20261017/selected-retained-typing-tail-051.png')},'contact_sheet_frames':[0,26,51],
 'observations':['Frame 0 is the intentional authored gap in all three columns. At frame 26 original/source-time and current output show source frame 25, archived output shows 24; both actual products show four yellow H glyphs.','At frame 51 archived output has a black background with yellow H; current output restores source frame 05 with the same visible yellow H. Selected output frame 51 confirms the restored background.'],
 'continuous_playback_reviewed':False,'audio_listening_reviewed':False,'general_visual_quality_accepted':False}
(out/'nested-frame-coverage-20261017.json').write_text(json.dumps(record,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
print(json.dumps({'full_tests':537,'adjacent_subset':79,'new_tests':13,'baseline_failures':8,'cli_calls':85,'public_files':len(files),'passed_deliveries':8,'failed_deliveries':2,'logs':len(logs)}),flush=True)
